"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["60708"],{92985(e){e.exports=JSON.parse('{"id":"FIN-122","slug":"consistency-principle","term":"Consistency Principle","also_known_as":[],"difficulty":"Beginner","definition":"The consistency principle is the accounting rule that a business should use the same accounting methods from one period to the next, so that its results can be compared fairly over time.","explanation":["Accounting often allows choices, such as how to value inventory or how quickly to depreciate equipment. If a company changed methods every year, its results could rise or fall simply because of the method used, not because of any real change in the business.","For example, if a company switched its depreciation method in a way that halved its annual depreciation charge, its profit would jump even though nothing about the business had improved. The consistency principle prevents this kind of distortion.","Consistency does not mean methods can never change. A company may change if a new method gives a more accurate picture or if accounting standards require it. When it does, it must disclose the change, explain why and show its effect, often by restating the figures for earlier periods so they remain comparable.","For readers of financial statements, consistency means trends can be trusted. Growth in revenue or profit over several years reflects the business itself rather than changes in how the numbers were calculated."],"note":"","total":1500,"prev":{"slug":"confirmation-bias","term":"Confirmation Bias"},"next":{"slug":"consolidation","term":"Consolidation"}}')}}]);